## 混合使用模式

最佳实践是结合两者：Store 管理全局业务状态，Composable 封装可复用逻辑：

```mermaid
flowchart TD
    subgraph Global["全局状态 → Store"]
        Auth["useAuthStore"]
        Cart["useCartStore"]
        Settings["useSettingsStore"]
    end
    subgraph Reusable["可复用逻辑 → Composable"]
        Fetch["useFetch"]
        Form["useFormValidation"]
        Mouse["useMouse"]
    end
    subgraph Component["组件"]
        C1["LoginForm"]
    end
    Component --> Global
    Component --> Reusable
```

```vue
<script setup lang="ts">
import { ref } from 'vue';
import { useAuthStore } from '@/stores/auth';
import { useFormValidation } from '@/composables/useFormValidation';

const authStore = useAuthStore();

const email = ref<string>('');
const password = ref<string>('');

const emailValidation = useFormValidation(email, [
  { validate: (v) => v.length > 0, message: '邮箱不能为空' },
  { validate: (v) => v.includes('@'), message: '邮箱格式不正确' },
]);

async function handleLogin() {
  emailValidation.touch();
  if (emailValidation.isValid.value) {
    await authStore.login(email.value, password.value);
  }
}
</script>
```

